/**
 * legado 书源格式语义覆盖矩阵（数据表）——「彻底兼容 legado」这条目标的**唯一读数口**。
 *
 * 本表把 legado 书源格式的每一条能力落成一行，每行必须归入三态之一：
 *   implemented    本仓已实现——`impl` 指向实现它的源码符号，`test` 指向钉住它的测试标题片段
 *   not-applicable 环境不适用，或格式里这条本就无消费方——`note` 写明这条裁决的理由
 *   open           已知欠账 / 待拍板——`note` 讲清缺什么、卡在谁手上，并带 `2026-MM-DD` 时效戳
 *
 * `note` 的体裁受 `docs/AGENTS.md` §3 第 14 条约束：只写本仓当前的口径、注意事项，以及挂在读数上
 * 的那一个时效锚；取证经过、复核轮次与未实测的推论是日志，外部项目的名字与代码路径不进来。
 *
 * 为什么做成机器守卫而不是文档：这些判据会被改名、被删、被写歪。`status-evidence.test.ts` 逐行验
 * 「实现符号在不在、钉子用例在不在、不适用有没有写明理由、开口行有没有时效戳」，任一条漂移即红——
 * 比人肉维护的清单可靠，也比「注释说已支持」诚实。
 *
 * 裁决理由住本行 `note`，不住别处：仓里没有第二份兼容裁决文档，写不出理由的那一行就是还没裁决。
 *
 * 刻意不设「未知」态：一行的归属只能是上面三态之一，写不出来就编译不过。
 */

export type CoverageStatus = 'implemented' | 'not-applicable' | 'open'

export type CoverageGroup =
  | 'A 规则语法' | 'B URL 与请求' | 'C 书源字段' | 'D 搜索与发现' | 'E 书籍详情'
  | 'F 目录' | 'G 正文' | 'H JS 宿主面' | 'I App 级规则族' | 'J 评论与源类型' | 'K 书源管理与调试'

export interface CoverageRow {
  /** 稳定 id：改名即断言失败，防止同一能力被抄成两行 */
  id: string
  group: CoverageGroup
  /** legado 书源格式里的能力名（尽量用格式侧的字段名与键名，便于与书源原文对账） */
  capability: string
  status: CoverageStatus
  /** [源码文件, 必须出现在该文件里的符号或原文] */
  impl?: [string, string]
  /** [测试文件, 必须出现在该文件里的用例标题片段] */
  test?: [string, string]
  /** 三态通用的说明：implemented 记当前口径与注意事项、not-applicable 记裁决理由、open 记欠什么、卡在谁手上 */
  note?: string
  /** 面 D 需求读数：键名住 `demand-keys.ts`；n 是写出时的现量，asOf 是时效锚 */
  demand?: Array<{ key: string; n: number; asOf: string }>
}

